package variant5_payrollsystem;

import java.io.FileOutputStream;
import java.io.FileWriter;
import java.io.IOException;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

// Опис предметної області: Бухгалтерський облік та розрахунок заробітної плати підприємства.
// Завдання коду: Розрахунок місячної заробітної плати працівника — валідація робочого часу, обчислення окладу, премій, податку на доходи фізичних осіб (ПДФО) та військового збору, створення розрахункового листка, експорт банківського реєстру та логування бухгалтерської операції.

public class EmployeePayrollData {
    private String employeeId;
    private String fullName;
    private String taxId; // РНОКПП / ІПН
    private BigDecimal baseHourlyRate;
    private int hoursWorked;
    private BigDecimal bonusAmount;
    private String bankCardNumber;

    public String getEmployeeId() { return employeeId; }
    public void setEmployeeId(String employeeId) { this.employeeId = employeeId; }

    public String getFullName() { return fullName; }
    public void setFullName(String fullName) { this.fullName = fullName; }

    public String getTaxId() { return taxId; }
    public void setTaxId(String taxId) { this.taxId = taxId; }

    public BigDecimal getBaseHourlyRate() { return baseHourlyRate; }
    public void setBaseHourlyRate(BigDecimal baseHourlyRate) { this.baseHourlyRate = baseHourlyRate; }

    public int getHoursWorked() { return hoursWorked; }
    public void setHoursWorked(int hoursWorked) { this.hoursWorked = hoursWorked; }

    public BigDecimal getBonusAmount() { return bonusAmount; }
    public void setBonusAmount(BigDecimal bonusAmount) { this.bonusAmount = bonusAmount; }

    public String getBankCardNumber() { return bankCardNumber; }
    public void setBankCardNumber(String bankCardNumber) { this.bankCardNumber = bankCardNumber; }
}

public class PayrollProcessor {
    public void calculateAndProcessSalary(EmployeePayrollData emp) {
        // 1. Перевірка вихідних бухгалтерських даних
        if (emp == null) {
            throw new IllegalArgumentException("Об'єкт emp не може бути null.");
        }

        if (emp.getTaxId() == null || emp.getTaxId().isBlank() || emp.getTaxId().length() != 10) {
            throw new IllegalArgumentException("Некоректний податковий номер (РНОКПП) співробітника.");
        }

        if (emp.getHoursWorked() < 0 || emp.getHoursWorked() > 350) {
            throw new IllegalArgumentException("Недопустима кількість відпрацьованих годин за місяць.");
        }

        // 2. Фінансові розрахунки (Нараховано, Податки, До виплати)
        BigDecimal baseSalary = emp.getBaseHourlyRate().multiply(BigDecimal.valueOf(emp.getHoursWorked()));
        BigDecimal grossSalary = baseSalary.add(emp.getBonusAmount());

        // Податки: ПДФО 18%, Військовий збір 1.5%
        BigDecimal pitTax = grossSalary.multiply(new BigDecimal("0.18"));
        BigDecimal militaryTax = grossSalary.multiply(new BigDecimal("0.015"));
        BigDecimal totalTaxes = pitTax.add(militaryTax);

        BigDecimal netSalary = grossSalary.subtract(totalTaxes);

        // 3. Формування розрахункового листка
        String paySlip = String.format(
                "--------------------------------------------------%n" +
                "РОЗРАХУНКОВИЙ ЛИСТОК ЗА МІСЯЦЬ%n" +
                "Співробітник: %s (ІПН: %s)%n" +
                "Відпрацьовано годин: %d год%n" +
                "--------------------------------------------------%n" +
                "Нараховано (Gross): %.2f грн%n" +
                "- Основна оплата: %.2f грн%n" +
                "- Премія: %.2f грн%n" +
                "Утримано податків: %.2f грн%n" +
                "- ПДФО (18%%): %.2f грн%n" +
                "- Військовий збір (1.5%%): %.2f грн%n" +
                "--------------------------------------------------%n" +
                "ДО ВИПЛАТИ (Net): %.2f грн%n" +
                "--------------------------------------------------",
                emp.getFullName(), emp.getTaxId(),
                emp.getHoursWorked(),
                grossSalary, baseSalary, emp.getBonusAmount(),
                totalTaxes, pitTax, militaryTax,
                netSalary
        );

        // 4. Експорт у файл реєстру виплат для банку
        String monthYear = LocalDate.now().format(DateTimeFormatter.ofPattern("MM_yyyy"));
        String bankRegistryRow = String.format("%s;%s;%.2f;UAH;Salary_%s%n", emp.getTaxId(), emp.getBankCardNumber(), netSalary, monthYear);
        try (FileOutputStream fos = new FileOutputStream("bank_payout_registry.csv", true)) {
            fos.write(bankRegistryRow.getBytes(StandardCharsets.UTF_8));
        } catch (IOException e) {
            System.err.println("Помилка запису банківського реєстру: " + e.getMessage());
        }

        // 5. Логування операції у системний журнал аудиту
        String logEntry = String.format("[%s] Audit Payroll: EmpID=%s, Gross=%.2f, Net=%.2f, Taxes=%.2f%n",
                Instant.now().toString(), emp.getEmployeeId(), grossSalary, netSalary, totalTaxes);
        try (FileWriter writer = new FileWriter("payroll_audit.log", true)) {
            writer.write(logEntry);
        } catch (IOException e) {
            System.err.println("Помилка логування аудиту: " + e.getMessage());
        }

        System.out.println(paySlip);
    }
}
